from pydantic import BaseModel, ConfigDict

class Pet:
    def __init__(self, name: str):
        self.name = name

class Model(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    pet: Pet

model = Model(pet=Pet("Fluffy"))
assert model.pet.name == "Fluffy"

from pydantic import BaseModel, ConfigDict

class Pet:
    def __init__(self, name: str):
        self.name = name

class Model(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    pet: Pet

model = Model(pet=Pet("Milo"))
print(model.pet.name)

from pydantic import BaseModel, ConfigDict

class User(BaseModel):
    model_config = ConfigDict(extra='allow')
    name: str

user = User(name='Ada', role='admin')
assert user.__pydantic_extra__ == {'role': 'admin'}

from pydantic import BaseModel, ConfigDict

class User(BaseModel):
    model_config = ConfigDict(frozen=True)
    name: str

user = User(name='Ada')
print(hash(user))
try:
    user.name = 'Grace'
except Exception as exc:
    print(type(exc).__name__)

from pydantic import BaseModel, ConfigDict

class Product(BaseModel):
    model_config = ConfigDict(
        json_schema_extra={"examples": [{"name": "Keyboard"}]}
    )
    name: str

print(Product.model_json_schema())

from pydantic import BaseModel, Field

class User(BaseModel):
    user_id: int = Field(alias='userId')

user = User(userId=7)
print(user.model_dump(by_alias=True))
# {'userId': 7}

from pydantic import BaseModel, ValidationError

class User(BaseModel):
    age: int

try:
    User(age="not an integer")
except ValidationError as exc:
    print(exc.errors())
